import{_ as p,o as i,c as a,ab as t}from"./chunks/framework.DCf1Sbhf.js";const x=JSON.parse('{"title":"关于像素的那些事","description":"","frontmatter":{},"headers":[],"relativePath":"front/css/index.md","filePath":"front/css/index.md","lastUpdated":1772158766000}'),o={name:"front/css/index.md"};function r(d,e,n,l,c,s){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="关于像素的那些事" tabindex="-1">关于像素的那些事 <a class="header-anchor" href="#关于像素的那些事" aria-label="Permalink to &quot;关于像素的那些事&quot;">​</a></h1><h2 id="基本概览" tabindex="-1">基本概览 <a class="header-anchor" href="#基本概览" aria-label="Permalink to &quot;基本概览&quot;">​</a></h2><h3 id="设备像素-device-pixel-dp" tabindex="-1">设备像素(device pixel, dp) <a class="header-anchor" href="#设备像素-device-pixel-dp" aria-label="Permalink to &quot;设备像素(device pixel, dp)&quot;">​</a></h3><p>又称为<em>物理像素</em>。指设备能控制显示的最小物理单位，意指显示器上一个个的点。 从屏幕在工厂生产出的那天起，它上面设备像素点就固定不变了，设备像素的特点就是大小固定，不可变。</p><h3 id="css像素-css-pixel-px" tabindex="-1">CSS像素(css pixel, px) <a class="header-anchor" href="#css像素-css-pixel-px" aria-label="Permalink to &quot;CSS像素(css pixel, px)&quot;">​</a></h3><p>CSS像素（css pixel, px）: 适用于web编程，在 CSS 中以 px 为后缀，是一个长度单位</p><p>在 CSS 规范中，长度单位可以分为两类，绝对单位以及相对单位</p><p>px是一个相对单位，相对的是设备像素（device pixel）</p><p>一般情况，页面缩放比为1，1个CSS像素等于1个设备独立像素 CSS像素又具有两个方面的相对性：</p><p>在同一个设备上，每1个 CSS 像素所代表的设备像素是可以变化的（比如调整屏幕的分辨率） 在不同的设备之间，每1个 CSS 像素所代表的设备像素是可以变化的（比如两个不同型号的手机） 在页面进行缩放操作也会 引起css中px的变化，假设页面放大一倍，原来的 1px 的东西变成 2px，在实际宽度不变的情况下1px 变得跟原来的 2px 的长度（长宽）一样了（元素会占据更多的设备像素）</p><p>假设原来需要 320px 才能填满的宽度现在只需要 160px</p><blockquote><p>px 都会受哪些因素的影响而变化</p><ol><li>每英寸像素(pixel per inch, ppi/PPI): 它表示的是每英寸所拥有的像素(pixel) 数目，更确切的说法应该是像素密度，放到显示器上说的是每英寸多少物理像素及显示器设备的点距。数值越高，代表显示屏能够以越高的密度显示图像。</li><li>设备像素比(device pixel ratio, dpr/DPR): 它描述的是未缩放状态下，设备像素和 CSS 像素的初始比例关系，也可以解释为默认缩放比例。如何理解这个概念呢？通俗来说，它是指在开发中1个 CSS 像素占用多少设备像素，如 dpr=2 代表1个 CSS 像素用2x2个设备像素来绘制，所以，可以理解为 1px由多少个设备像素组成</li></ol></blockquote><h3 id="设备独立像素-device-independent-pixel-dip" tabindex="-1">设备独立像素(Device independent Pixel, DIP) <a class="header-anchor" href="#设备独立像素-device-independent-pixel-dip" aria-label="Permalink to &quot;设备独立像素(Device independent Pixel, DIP)&quot;">​</a></h3><p>设备独立像素（Device Independent Pixel）：也称为逻辑像素（与设备无关的逻辑像素)，代表可以通过程序控制使用的虚拟像素， 单位 pt。pt 在 css 单位中属于真正的绝对单位， 在javaScript中可以通过<code>window.screen.width/ window.screen.height</code> 查看</p><p>一个设备独立像素里可能包含1个或者多个物理像素点，包含的越多则屏幕看起来越清.</p><p>至于为什么出现设备独立像素这种虚拟像素单位概念，下面举个例子：</p><p>iPhone 3GS 和 iPhone 4/4s 的尺寸都是 3.5 寸，但 iPhone 3GS 的分辨率是 320x480，iPhone 4/4s 的分辨率是 640x960</p><p>这意味着，iPhone 3GS 有 320 个物理像素，iPhone 4/4s 有 640 个物理像素</p><p>如果我们按照真实的物理像素进行布局，比如说我们按照 320 物理像素进行布局，到了 640 物理像素的手机上就会有一半的空白，为了避免这种问题，就产生了虚拟像素单位</p><p>我们统一 iPhone 3GS 和 iPhone 4/4s 都是 320 个虚拟像素，只是在 iPhone 3GS 上，最终 1 个虚拟像素换算成 1 个物理像素，在 iphone 4s 中，1 个虚拟像素最终换算成 2 个物理像素</p><p>至于 1 个虚拟像素被换算成几个物理像素，这个数值我们称之为设备像素比，也就是下面介绍的dpr</p><h3 id="设备像素比-device-pixel-ratio-dpr-dpr" tabindex="-1">设备像素比(device pixel ratio, dpr/DPR) <a class="header-anchor" href="#设备像素比-device-pixel-ratio-dpr-dpr" aria-label="Permalink to &quot;设备像素比(device pixel ratio, dpr/DPR)&quot;">​</a></h3><p>它描述的是未缩放状态下，设备像素和 CSS 像素的初始比例关系，也可以解释为默认缩放比例. 代表设备像素到设备独立像素的转换关系，在JavaScript中可以通过 <code>window.devicePixelRatio</code> 获取</p><p>计算公式如下：</p><p>当设备像素比为1:1时，使用1（1×1）个设备像素显示1个CSS像素</p><p>当设备像素比为2:1时，使用4（2×2）个设备像素显示1个CSS像素</p><p>当设备像素比为3:1时，使用9（3×3）个设备像素显示1个CSS像素</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>无缩放情况下，1个CSS像素等于1个设备独立像素</p><p>设备像素由屏幕生产之后就不发生改变，而设备独立像素是一个虚拟单位会发生改变</p><p>PC端中，1个设备独立像素 = 1个设备像素 （在100%，未缩放的情况下）</p><p>在移动端中，标准屏幕（160ppi）下 1个设备独立像素 = 1个设备像素</p><p>设备像素比（dpr） = 设备像素 / 设备独立像素</p><p>每英寸像素（ppi），值越大，图像越清晰</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><p><a href="https://hijiangtao.github.io/2017/07/09/Device-Viewport-and-Pixel-Introduction/" target="_blank" rel="noreferrer">https://hijiangtao.github.io/2017/07/09/Device-Viewport-and-Pixel-Introduction/</a></p>',36)])])}const S=p(o,[["render",r]]);export{x as __pageData,S as default};
